"""Represent retrieval hits, generated sections and validation findings."""

from pydantic import BaseModel, Field

from models.metadata import Metadata


class RetrievalResult(BaseModel):
    """Retrieved chunk with similarity score.

    Attributes:
        content (str): Source text or Markdown content to process.
        score (float): Score.
    """

    metadata: Metadata

    content: str

    score: float


class GeneratedSection(BaseModel):
    """Markdown generated by the writer.

    Attributes:
        title (str): Requested page title or source label.
        markdown (str): Markdown text to normalize, split or inspect.
        sources (list[str]): Sources.
    """

    title: str

    markdown: str

    sources: list[str] = Field(default_factory=list)


class ValidationReport(BaseModel):
    """Validation output for a generated section.

    Attributes:
        section (str): Section.
        passed (bool): Passed.
        issues (list[str]): Issues.
    """

    section: str

    passed: bool

    issues: list[str] = Field(default_factory=list)
